class Solution {
  public boolean differByOne(String[] dict) {
    Set<String> seen = new HashSet<>();
    for (String word : dict) {
      char[] chars = word.toCharArray();
      for (int i = 0; i < chars.length; i++) {
        char saved = chars[i];
        chars[i] = '*';
        // two words differ in exactly one place iff they collide once that place is masked
        if (!seen.add(new String(chars))) return true;
        chars[i] = saved;
      }
    }
    return false;
  }
}
